/** Write the files, skipping any a person has taken over (marker removed). Returns the paths left alone. */
export function writeClientRepo(project: string, files: Record<string, string>): string[] {
	const kept: string[] = [];
	for (const [rel, content] of Object.entries(files)) {
		const file = join(project, rel);
		if (existsSync(file) && !readFileSync(file, "utf8").split("\n", 3).some((l) => l.includes(MARKER))) {
			kept.push(rel);
			continue;
		}
		mkdirSync(dirname(file), { recursive: true });
		writeFileSync(file, content);
	}
	return kept;
}
